const baza = { x: 1, y: 2, z: 3 };
const rozszerzony = { ...baza, w: 4, y: 100 };
console.log(rozszerzony); // { x: 1, y: 100, z: 3, w: 4 }
// y: 100 wygralo, bo zostalo podane PO ...baza w kolejnosci zapisu

const uzytkownik = { imie: "Piotr", punkty: [10, 20] };
const kopia = { ...uzytkownik };
kopia.imie = "Marek";

console.log(uzytkownik.imie); // "Piotr" - niezmieniony
console.log(kopia.imie);      // "Marek"

const uzytkownik = { imie: "Piotr", punkty: [10, 20] };
const kopia = { ...uzytkownik };
kopia.punkty.push(30);

console.log(uzytkownik.punkty); // [10, 20, 30] - ZMIENIONY!
// spread to kopia PLYTKA - punkty w obu obiektach to TA SAMA referencja tablicy,
// wiec modyfikacja przez kopie wplywa rowniez na oryginal

function zaktualizujProfil(profil, zmiany) {
  return { ...profil, ...zmiany };
}

const profil = { id: 1, imie: "Jan", aktywny: true };
const zaktualizowany = zaktualizujProfil(profil, { aktywny: false });

console.log(zaktualizowany); // { id: 1, imie: 'Jan', aktywny: false }
console.log(profil);         // { id: 1, imie: 'Jan', aktywny: true } - NIEZMIENIONY

const stan = { zalogowany: false, uzytkownik: null };
const nowyStan = { ...stan, zalogowany: true, uzytkownik: { imie: "Ala" } };

console.log(nowyStan); // { zalogowany: true, uzytkownik: { imie: 'Ala' } }
console.log(stan);     // { zalogowany: false, uzytkownik: null } - NIEZMIENIONY

const warstwa1 = { a: 1 };
const warstwa2 = { b: 2 };
const warstwa3 = { a: 99, c: 3 };

const polaczone = { ...warstwa1, ...warstwa2, ...warstwa3 };
console.log(polaczone); // { a: 99, b: 2, c: 3 }
// a: 99 (z warstwa3) wygrywa, bo warstwa3 jest OSTATNIA w kolejnosci spreadu

const state = { loading: false, user: null };
const bledny = { loading: true, ...state };
console.log(bledny); // { loading: false, user: null } - loading NIE zmienione!

const state = { loading: false, user: null };
const poprawny = { ...state, loading: true };
console.log(poprawny); // { loading: true, user: null } - POPRAWNIE zmienione

const domyslneOpcje = { rozmiar: "M", kolor: "czarny", dostepnosc: true };

function stworzZamowienie(opcje) {
  return { ...domyslneOpcje, ...opcje };
}

console.log(stworzZamowienie({ kolor: "czerwony" }));
// { rozmiar: 'M', kolor: 'czerwony', dostepnosc: true }

const produkt = { nazwa: "Kubek", cena: 25 };
const zWaluta = { ...produkt, waluta: "PLN" };

console.log(Object.keys(produkt).length);  // 2
console.log(Object.keys(zWaluta).length);   // 3

function usunPole(obiekt, kluczDoUsuniecia) {
  const { [kluczDoUsuniecia]: pominiety, ...reszta } = obiekt;
  return reszta;
}

console.log(usunPole({ a: 1, b: 2, c: 3 }, "b")); // { a: 1, c: 3 }

const stan = { licznik: 5, historia: [1, 2, 3] };
const nowyStan = { ...stan, licznik: stan.licznik + 1 };

console.log(nowyStan); // { licznik: 6, historia: [1, 2, 3] }
console.log(stan);     // { licznik: 5, historia: [1, 2, 3] } - NIEZMIENIONY

const zadania = [{ id: 1, zrobione: false }, { id: 2, zrobione: false }];
const zaktualizowane = zadania.map(z => z.id === 1 ? { ...z, zrobione: true } : z);

console.log(zaktualizowane);
// [{ id: 1, zrobione: true }, { id: 2, zrobione: false }]

const a = { x: 1 };
const wynik = { ...a, ...{} };
console.log(wynik); // { x: 1 } - bez zmian

function polaczKonfiguracje(...konfiguracje) {
  return konfiguracje.reduce((wynik, k) => ({ ...wynik, ...k }), {});
}

console.log(polaczKonfiguracje({ a: 1 }, { b: 2 }, { a: 99 })); // { a: 99, b: 2 }

const uzytkownik = { imie: "Jan", hasloHash: "xyz123" };
const { hasloHash, ...bezpiecznyUzytkownik } = uzytkownik;
console.log(bezpiecznyUzytkownik); // { imie: 'Jan' }

const formularz = { imie: "Ala", email: "", wiek: 0 };
const kopia = { ...formularz };
console.log(kopia); // { imie: 'Ala', email: '', wiek: 0 } - WSZYSTKIE wartosci zachowane, w tym falsy

function odwrocMotyw(motyw) {
  return { ...motyw, tlo: motyw.tekst, tekst: motyw.tlo };
}

console.log(odwrocMotyw({ tlo: "bialy", tekst: "czarny" }));
// { tlo: 'czarny', tekst: 'bialy' }

const stan = { filtry: { kategoria: "wszystkie", cena: null }, sortowanie: "nazwa" };
const nowyStan = { ...stan, filtry: { ...stan.filtry, kategoria: "elektronika" } };

console.log(nowyStan);
// { filtry: { kategoria: 'elektronika', cena: null }, sortowanie: 'nazwa' }
console.log(stan.filtry.kategoria); // "wszystkie" - oryginal NIENARUSZONY

const licznikStatystyk = { wizyty: 100, klikniecia: 50 };
const wyzerowany = Object.fromEntries(
  Object.entries(licznikStatystyk).map(([k]) => [k, 0])
);
console.log(wyzerowany); // { wizyty: 0, klikniecia: 0 }

function przelaczFlage(obiekt, klucz) {
  return { ...obiekt, [klucz]: !obiekt[klucz] };
}

console.log(przelaczFlage({ aktywny: true }, "aktywny")); // { aktywny: false }

const a = { ustawienia: { x: 1, y: 2 } };
const b = { ustawienia: { y: 99 } };
const polaczone = { ...a, ...b };

console.log(polaczone.ustawienia); // { y: 99 } - x ZNIKNELO, spread NIE jest rekurencyjny

const a = { ustawienia: { x: 1, y: 2 } };
const b = { ustawienia: { y: 99 } };
const poprawnie = { ...a, ustawienia: { ...a.ustawienia, ...b.ustawienia } };

console.log(poprawnie.ustawienia); // { x: 1, y: 99 } - POPRAWNIE scalone

function zastosujRabat(produkty, procent) {
  return produkty.map(p => ({ ...p, cena: p.cena * (1 - procent / 100) }));
}

console.log(zastosujRabat([{ id: 1, cena: 100 }, { id: 2, cena: 200 }], 10));
// [{ id: 1, cena: 90 }, { id: 2, cena: 180 }]

const pusty = {};
const pelny = { a: 1, b: 2 };

console.log({ ...pusty } === pusty); // false
console.log({ ...pelny } === pelny); // false

const osoba = { imie: "Jan", wiek: 30, email: "jan@test.pl" };
const { imie, ...reszta } = osoba;
const tylkoImie = { imie };

console.log(tylkoImie); // { imie: 'Jan' }
console.log(reszta);    // { wiek: 30, email: 'jan@test.pl' }

const koszyk = { produkty: ["chleb"], suma: 5 };
const nowyKoszyk = { ...koszyk, produkty: [...koszyk.produkty, "mleko"] };

console.log(nowyKoszyk); // { produkty: ['chleb', 'mleko'], suma: 5 }
console.log(koszyk);     // { produkty: ['chleb'], suma: 5 } - NIEZMIENIONY

const ustawienia = { motyw: "jasny", jezyk: "pl" };

function resetujDoDomyslnych() {
  return { motyw: "jasny", jezyk: "pl" };
}

const zresetowane = resetujDoDomyslnych();
console.log(zresetowane === ustawienia); // false - rozne obiekty, mimo identycznej zawartosci

const profil = { imie: "Ola", wiek: 25 };
const zWielkimiKluczami = Object.fromEntries(
  Object.entries(profil).map(([k, v]) => [k.toUpperCase(), v])
);
console.log(zWielkimiKluczami); // { IMIE: 'Ola', WIEK: 25 }

